function EXTRA(R,ICON){
 /* hook: the data sheet gives h; the chain wants ABCD */
 ICON.ctSheet=(x,y)=>`<g transform="translate(${x-200} ${y-95})">${CT_box(0,0,400,190,{st:BLU,sw:3,r:18})}${CT_T(24,40,'TRANSISTOR DATA SHEET',{fs:22,fw:800,fill:BLU})}${CT_L(24,56,376,56,'#CED4DA',2)}${CT_T(24,100,'h₁₁ = 1 kΩ',{fs:24,fw:700})}${CT_T(210,100,'h₁₂ = 2.5 × 10⁻⁴',{fs:24,fw:700})}${CT_T(24,146,'h₂₁ = 50',{fs:24,fw:700})}${CT_T(210,146,'h₂₂ = 25 μS',{fs:24,fw:700})}</g>`;
 ICON.ctChain=(x,y)=>`<g transform="translate(${x-200} ${y-95})">${CT_box(0,0,400,190,{st:ORG,sw:3,r:18})}${CT_T(24,40,'THE DESIGN: A CHAIN',{fs:22,fw:800,fill:ORG})}${CT_2p(40,70,130,60,'transistor',BLU,{fs:20})}${CT_2p(230,70,130,60,'filter',GRN,{fs:22})}${CT_T(200,170,'needs ABCD',{fs:24,fw:800,a:'middle',fill:ORG})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.ctConv=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><rect x="-14" y="10" width="448" height="320" rx="18" fill="#EDF2FF"/>${[['Z',90,80],['Y',330,80],['h',90,250],['ABCD',330,250]].map(([t,xx,yy])=>`<rect x="${xx-70}" y="${yy-44}" width="140" height="88" rx="14" fill="#FFFFFF" stroke="${BLU}" stroke-width="4"/>`+CT_T(xx,yy+14,t,{fs:t.length>1?32:40,fw:800,a:'middle',fill:BLU})).join('')}${CT_arrow(166,80,252,80,ORG,4)}${CT_arrow(90,130,90,198,ORG,4)}${CT_arrow(330,130,330,198,ORG,4)}${CT_T(210,180,'algebra',{fs:26,fw:800,a:'middle',fill:ORG})}</g>`;
 ICON.ctInv=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_mat(90,90,[['6','4'],['4','7']],{fs:34,cw:52})}${CT_T(150,52,'−1',{fs:26,fw:800})}${CT_T(200,100,'=',{fs:36,fw:800,a:'middle'})}${CT_T(262,100,'1/26',{fs:30,fw:800,a:'middle',fill:ORG})}${CT_mat(370,90,[['7','−4'],['−4','6']],{fs:34,cw:62,col:ORG})}${CT_mat(210,250,[['1/6','…'],['…','1/7']],{fs:34,cw:96,col:CT_AX})}${CT_L(110,200,310,300,TRED,8,'stroke-opacity=".8"')}</g>`;
 ICON.ctConn=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_pair(70,0,90,40,12,'s',{fs:22})}${CT_T(250,62,'series: Z +',{fs:28,fw:800,fill:BLU})}${CT_pair(80,128,80,40,12,'p',{fs:22})}${CT_T(250,190,'parallel: Y +',{fs:28,fw:800,fill:BLU})}${CT_2p(30,262,80,40,'a',BLU,{fs:22})}${CT_2p(146,262,80,40,'b',GRN,{fs:22})}${CT_T(262,292,'cascade: T ×',{fs:28,fw:800,fill:GRN})}</g>`;
}
